67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Dedicated audit logger. A successful owner create emits a single line here carrying the new
74	     * owner's id, customer code, registration date and membership level, so the create side-effect
75	     * can be audited independently of the application log.
76	     */
77	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
78	
79	    private final ClinicService clinicService;
80	
81	    private final OwnerMapper ownerMapper;
82	
83	    private final PetMapper petMapper;
84	
85	    private final VisitMapper visitMapper;
86	
87	    /**
88	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
89	     * and a domain containing at least one dot, with no whitespace in any segment.
90	     */
91	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
92	
93	    /**
94	     * Required national-number length per E.164 country code. A normalized telephone whose country
95	     * code appears here must carry exactly this many national digits after the code; Australia
96	     * ({@code +61}) requires 9 and the North American Numbering Plan ({@code +1}) requires 10.
97	     * Country codes not listed are only subject to the generic 8-to-15 total-digit rule.
98	     */
99	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTH = Map.of("61", 9, "1", 10);
100	
101	    /**
102	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
103	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
104	     */
105	    private static final int MAX_OWNERS_PER_CITY = 50;
106	
107	    /**
108	     * Maximum number of owners that may be registered on a single day (by registration date). A create
109	     * attempted once this many owners already carry today's registration date is rejected with a
110	     * 429 Too Many Requests.
111	     */
112	    private static final int MAX_OWNERS_PER_DAY = 100;
113	
114	    /**
115	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
116	     * owners already carry the new owner's registration date, the created owner is flagged
117	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
118	     */
119	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
120	
121	    /**
122	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
123	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
124	     */
125	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
126	        "ST", "STREET",
127	        "RD", "ROAD",
128	        "AVE", "AVENUE");
129	
130	    /**
131	     * Inclusive 4-digit postcode range permitted per region, keyed by the region derived from the
132	     * owner's city ({@link Owner#getLocality()}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A
133	     * region not listed (the {@code 'UNKNOWN'} locality of a city with no known region) accepts any
134	     * 4-digit postcode.
135	     */
136	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
137	        "NSW", new int[] {2000, 2099},
138	        "VIC", new int[] {3000, 3099},
139	        "QLD", new int[] {4000, 4099});
140	
141	    public OwnerRestControllerV1(ClinicService clinicService,
142	                                 OwnerMapper ownerMapper,
143	                                 PetMapper petMapper,
144	                                 VisitMapper visitMapper) {
145	        this.clinicService = clinicService;
146	        this.ownerMapper = ownerMapper;
147	        this.petMapper = petMapper;
148	        this.visitMapper = visitMapper;
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
154	        Collection<Owner> owners;
155	        if (lastName != null) {
156	            owners = this.clinicService.findOwnerByLastName(lastName);
157	        } else {
158	            owners = this.clinicService.findAllOwners();
159	        }
160	        if (owners.isEmpty()) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
179	        validateRequiredFields(ownerFieldsDto);
180	        HttpHeaders headers = new HttpHeaders();
181	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
182	        rejectFutureRegistrationDate(owner.getRegistrationDate());
183	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
184	        owner.setRegistrationDate(registrationDate);
185	        requireDailyCapacity(registrationDate);
186	        requireCityHasCapacity(owner.getCity());
187	        validatePostcode(owner);
188	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
189	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
190	            joinHousehold(owner);
191	        }
192	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
193	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
194	        requireUniqueIdentity(owner);
195	        flagPossibleDuplicate(owner);
196	        owner.setCustomerCode(owner.buildCustomerCode());
197	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
198	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
199	        this.clinicService.saveOwner(owner);
200	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
201	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
202	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
203	        headers.setLocation(UriComponentsBuilder.newInstance()
204	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
205	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
206	    }
207	
208	    /**
209	     * Rejects a create whose supplied registration date is later than the server's current date. A
210	     * registration may be back-dated but never post-dated, so a future date is treated as a client
211	     * error. A {@code null} supplied date (the client omitted it) is allowed, as it defaults to the
212	     * server date.
213	     *
214	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when the
215	     *     client omitted it
216	     * @throws FutureRegistrationDateException if the supplied date is after the server's current date
217	     */
218	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
219	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
220	            throw new FutureRegistrationDateException(suppliedRegistrationDate);
221	        }
222	    }
223	
224	    /**
225	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
226	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
227	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
228	     * existed prior to this create.
229	     *
230	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
231	     *     a business day
232	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
233	     *     registered on that business day
234	     */
235	    private void requireDailyCapacity(LocalDate registrationDate) {
236	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
237	            throw new DailyOwnerLimitException(registrationDate);
238	        }
239	    }
240	
241	    /**
242	     * Counts the existing owners whose registration date equals the given business-day date. This is
243	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
244	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
245	     * the bulk-signup warning.
246	     *
247	     * @param registrationDate the effective business-day registration date to count against
248	     * @return the number of pre-existing owners registered on that date
249	     */
250	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
251	        return this.clinicService.findAllOwners().stream()
252	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
253	            .count();
254	    }
255	
256	    /**
257	     * Rejects an owner whose city already contains the maximum allowed number of owners
258	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
259	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
260	     * create.
261	     *
262	     * @param city the city of the owner being created
263	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
264	     */
265	    private void requireCityHasCapacity(String city) {
266	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
267	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
268	            .count();
269	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
270	            throw new CityOwnerLimitException(city);
271	        }
272	    }
273	
274	    /**
275	     * Validates a supplied postcode against the owner's region. Postcode is optional: an owner with no
276	     * postcode is accepted unchanged. When present it is a 4-digit string (enforced by the request
277	     * schema) that must fall within the inclusive range permitted for the region derived from the
278	     * owner's city ({@link #REGION_POSTCODE_RANGES}); a city whose region is unknown accepts any 4-digit
279	     * postcode. An out-of-range postcode is rejected with a 400 Bad Request.
280	     *
281	     * @param owner the owner being created, with its city and postcode set
282	     * @throws InvalidOwnerFieldsException if a supplied postcode is out of range for the city's region
283	     */
284	    private void validatePostcode(Owner owner) {
285	        String postcode = owner.getPostcode();
286	        if (postcode == null) {
287	            return;
288	        }
289	        int[] range = REGION_POSTCODE_RANGES.get(owner.getLocality());
290	        if (range == null) {
291	            return;
292	        }
293	        int value = Integer.parseInt(postcode);
294	        if (value < range[0] || value > range[1]) {
295	            throw new InvalidOwnerFieldsException(List.of("postcode"));
296	        }
297	    }
298	
299	    /**
300	     * Counts the existing owners that already share the given first name and last name, compared
301	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
302	     * owners that existed prior to this create.
303	     *
304	     * @param firstName the first name of the owner being created
305	     * @param lastName the last name of the owner being created
306	     * @return the number of pre-existing namesakes
307	     */
308	    private int countNamesakes(String firstName, String lastName) {
309	        return (int) this.clinicService.findAllOwners().stream()
310	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
311	                && equalsIgnoreCase(existing.getLastName(), lastName))
312	            .count();
313	    }
314	
315	    /**
316	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
317	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
318	     *
319	     * @param a the first value, possibly {@code null}
320	     * @param b the second value, possibly {@code null}
321	     * @return whether the values are equal ignoring case
322	     */
323	    private boolean equalsIgnoreCase(String a, String b) {
324	        return a == null ? b == null : a.equalsIgnoreCase(b);
325	    }
326	
327	    /**
328	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
329	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
330	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
331	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
332	     *
333	     * @param ownerFieldsDto the submitted owner fields
334	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
335	     */
336	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
337	        List<String> invalidFields = new ArrayList<>();
338	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
339	            invalidFields.add("firstName");
340	        }
341	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
342	            invalidFields.add("lastName");
343	        }
344	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
345	            invalidFields.add("address");
346	        }
347	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
348	            invalidFields.add("city");
349	        }
350	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
351	            invalidFields.add("telephone");
352	        }
353	        if (!invalidFields.isEmpty()) {
354	            throw new InvalidOwnerFieldsException(invalidFields);
355	        }
356	    }
357	
358	    /**
359	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
360	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
361	     * what gets stored and returned.
362	     *
363	     * @param telephone the raw telephone value from the request
364	     * @return the normalized E.164 telephone number
365	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
366	     */
367	    private String normalizeTelephone(String telephone) {
368	        String e164 = toE164(telephone);
369	        if (e164 == null) {
370	            throw new InvalidOwnerFieldsException(List.of("telephone"));
371	        }
372	        return e164;
373	    }
374	
375	    /**
376	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
377	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
378	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
379	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
380	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
381	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
382	     *
383	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
384	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
385	     *
386	     * @param telephone the raw telephone value, possibly {@code null}
387	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
388	     */
389	    private String toE164(String telephone) {
390	        if (telephone == null) {
391	            return null;
392	        }
393	        String cleaned = telephone.replaceAll("[ \\-()]", "");
394	        String digits;
395	        if (cleaned.startsWith("+")) {
396	            digits = cleaned.substring(1);
397	        } else {
398	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
399	            digits = "61" + national;
400	        }
401	        if (!digits.matches("[0-9]{8,15}")) {
402	            return null;
403	        }
404	        if (!nationalNumberLengthValid(digits)) {
405	            return null;
406	        }
407	        return "+" + digits;
408	    }
409	
410	    /**
411	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
412	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
413	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
414	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
415	     * accepted, leaving only the generic total-length rule to apply.
416	     *
417	     * @param digits the E.164 digits without the leading {@code '+'}
418	     * @return {@code true} if the national-number length matches the country code's requirement
419	     */
420	    private boolean nationalNumberLengthValid(String digits) {
421	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
422	            String code = entry.getKey();
423	            if (digits.startsWith(code)) {
424	                return digits.length() - code.length() == entry.getValue();
425	            }
426	        }
427	        return true;
428	    }
429	
430	    /**
431	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
432	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
433	     * and returned lower-cased.
434	     *
435	     * @param email the raw email value from the request, possibly {@code null}
436	     * @return the lower-cased email, or {@code null} when none was supplied
437	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
438	     */
439	    private String normalizeEmail(String email) {
440	        if (!StringUtils.hasText(email)) {
441	            return null;
442	        }
443	        String trimmed = email.trim();
444	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
445	            throw new InvalidOwnerFieldsException(List.of("email"));
446	        }
447	        return trimmed.toLowerCase(Locale.ROOT);
448	    }
449	
450	    /**
451	     * Rejects an owner whose whole identity key is already used by an existing owner. This is the
452	     * single consolidated duplicate check: the identity key ({@link Owner#getIdentityKey()}) is the
453	     * owner's normalized telephone, email (empty when absent) and household id joined with
454	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
455	     * owner's. Because the telephone is part of the key, two members of the same household
456	     * (same {@code householdId}) with different telephones have different identity keys and are both
457	     * allowed.
458	     *
459	     * @param owner the owner being created, with its normalized telephone, email and household id set
460	     * @throws DuplicateIdentityException if another owner already has this identity key
461	     */
462	    private void requireUniqueIdentity(Owner owner) {
463	        String identityKey = owner.getIdentityKey();
464	        boolean inUse = this.clinicService.findAllOwners().stream()
465	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
466	        if (inUse) {
467	            throw new DuplicateIdentityException(identityKey);
468	        }
469	    }
470	
471	    /**
472	     * Flags the owner being created as a possible (soft) duplicate of an existing owner. A soft match is
473	     * not a hard duplicate (its identity key is unique, already enforced by {@link #requireUniqueIdentity})
474	     * but it shares an existing owner's last name (compared case-insensitively) and postcode (both
475	     * present and equal) while carrying a different normalized telephone. When such an existing owner is
476	     * found the created owner is flagged ({@code possibleDuplicate} true) with {@code possibleDuplicateOf}
477	     * set to that owner's id; the lowest matching id is used when several owners match. Otherwise the flag
478	     * is false and {@code possibleDuplicateOf} is left unset.
479	     *
480	     * @param owner the owner being created, with its normalized telephone and postcode set
481	     */
482	    private void flagPossibleDuplicate(Owner owner) {
483	        if (owner.getPostcode() == null) {
484	            owner.setPossibleDuplicate(false);
485	            return;
486	        }
487	        Integer matchId = this.clinicService.findAllOwners().stream()
488	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
489	                && owner.getPostcode().equals(existing.getPostcode())
490	                && !owner.getTelephone().equals(existing.getTelephone()))
491	            .map(Owner::getId)
492	            .min(Integer::compareTo)
493	            .orElse(null);
494	        owner.setPossibleDuplicate(matchId != null);
495	        owner.setPossibleDuplicateOf(matchId);
496	    }
497	
498	    /**
499	     * Returns the existing owners that belong to the same household as the given last name and
500	     * address, i.e. those whose last name and address match case-insensitively and with runs of
501	     * whitespace collapsed to a single space.
502	     *
503	     * @param lastName the last name to match
504	     * @param address the address to match
505	     * @return the matching owners (possibly empty, never {@code null})
506	     */
507	    private List<Owner> findHouseholdMembers(String lastName, String address) {
508	        String normalizedLastName = normalizeForHousehold(lastName);
509	        String normalizedAddress = normalizeAddress(address);
510	        return this.clinicService.findAllOwners().stream()
511	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
512	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
513	            .toList();
514	    }
515	
516	    /**
517	     * Joins the owner being created to the shared household of any existing owner(s) that have the
518	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
519	     * member of the household - the existing owners and the new one - is assigned the same stable
520	     * {@code householdId}, so the shared identifier can be read back from any of them.
521	     *
522	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
523	     * the owner is left without a {@code householdId}.
524	     *
525	     * <p>Every member of the household - the existing owners and the new one - is also stamped with
526	     * the household's member count after this create ({@code householdSize}), so the shared size can
527	     * be read back from any of them.
528	     *
529	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
530	     */
531	    private void joinHousehold(Owner owner) {
532	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
533	        if (members.isEmpty()) {
534	            return;
535	        }
536	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
537	        int householdSize = members.size() + 1;
538	        owner.setHouseholdId(householdId);
539	        owner.setHouseholdSize(householdSize);
540	        for (Owner member : members) {
541	            member.setHouseholdId(householdId);
542	            member.setHouseholdSize(householdSize);
543	            this.clinicService.saveOwner(member);
544	        }
545	    }
546	
547	    /**
548	     * Computes the stable, shared household identifier for a last name and address. The value is
549	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
550	     * name and address, so every owner in the same household computes the same identifier.
551	     *
552	     * @param lastName the last name of the household
553	     * @param address the address of the household
554	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
555	     */
556	    private String computeHouseholdId(String lastName, String address) {
557	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
558	        try {
559	            byte[] digest = MessageDigest.getInstance("SHA-256")
560	                .digest(key.getBytes(StandardCharsets.UTF_8));
561	            StringBuilder hex = new StringBuilder();
562	            for (int i = 0; i < 6; i++) {
563	                hex.append(String.format("%02X", digest[i]));
564	            }
565	            return "HH-" + hex;
566	        } catch (NoSuchAlgorithmException e) {
567	            throw new IllegalStateException("SHA-256 algorithm not available", e);
568	        }
569	    }
570	
571	    /**
572	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
573	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
574	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
575	     *
576	     * @param value the raw value, possibly {@code null}
577	     * @return the normalized value
578	     */
579	    private String normalizeForHousehold(String value) {
580	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
581	    }
582	
583	    /**
584	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
585	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
586	     * value yields an empty string.
587	     *
588	     * @param value the raw value, possibly {@code null}
589	     * @return the trimmed, whitespace-collapsed value
590	     */
591	    private String collapseWhitespace(String value) {
592	        if (value == null) {
593	            return "";
594	        }
595	        return value.trim().replaceAll("\\s+", " ");
596	    }
597	
598	    /**
599	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
600	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
601	     * is upper-cased, and common street-type abbreviations are expanded as whole words
602	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
603	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
604	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
605	     *
606	     * @param address the raw address value, possibly {@code null}
607	     * @return the normalized address
608	     */
609	    private String normalizeAddress(String address) {
610	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
611	        if (collapsed.isEmpty()) {
612	            return "";
613	        }
614	        String[] tokens = collapsed.split(" ");
615	        StringBuilder normalized = new StringBuilder();
616	        for (int i = 0; i < tokens.length; i++) {
617	            if (i > 0) {
618	                normalized.append(' ');
619	            }
620	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
621	        }
622	        return normalized.toString();
623	    }
624	
625	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
626	    @Override
627	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
628	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
629	        if (currentOwner == null) {
630	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
631	        }
632	        currentOwner.setAddress(ownerFieldsDto.getAddress());
633	        currentOwner.setCity(ownerFieldsDto.getCity());
634	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
635	        currentOwner.setLastName(ownerFieldsDto.getLastName());
636	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
637	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
638	        this.clinicService.saveOwner(currentOwner);
639	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
640	    }
641	
642	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
643	    @Transactional
644	    @Override
645	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
646	        Owner owner = this.clinicService.findOwnerById(ownerId);
647	        if (owner == null) {
648	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
649	        }
650	        this.clinicService.deleteOwner(owner);
651	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
652	    }
653	
654	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
655	    @Override
656	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
657	        Owner owner = this.clinicService.findOwnerById(ownerId);
658	        if (owner == null) {
659	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
660	        }
661	        HttpHeaders headers = new HttpHeaders();
662	        Pet pet = petMapper.toPet(petFieldsDto);
663	        owner.setId(ownerId);
664	        pet.setOwner(owner);
665	        pet.getType().setName(null);
666	        this.clinicService.savePet(pet);
667	        PetDto petDto = petMapper.toPetDto(pet);
668	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
669	            .buildAndExpand(pet.getId()).toUri());
670	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
671	    }
672	
673	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
674	    @Override
675	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
676	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
677	        if (currentOwner != null) {
678	            Pet currentPet = this.clinicService.findPetById(petId);
679	            if (currentPet != null) {
680	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
681	                currentPet.setName(petFieldsDto.getName());
682	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
683	                this.clinicService.savePet(currentPet);
684	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
685	            }
686	        }
687	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
688	    }
689	
690	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
691	    @Override
692	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
693	        HttpHeaders headers = new HttpHeaders();
694	        Visit visit = visitMapper.toVisit(visitFieldsDto);
695	        Pet pet = new Pet();
696	        pet.setId(petId);
697	        visit.setPet(pet);
698	        this.clinicService.saveVisit(visit);
699	        VisitDto visitDto = visitMapper.toVisitDto(visit);
700	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
701	            .buildAndExpand(visit.getId()).toUri());
702	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
703	    }
704	
705	
706	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
707	    @Override
708	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
709	        Owner owner = this.clinicService.findOwnerById(ownerId);
710	        if (owner != null) {
711	            Pet pet = owner.getPet(petId);
712	            if (pet != null) {
713	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
714	            }
715	        }
716	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
717	    }
718	}
